<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Emergencies" />
    <EmergencyListFilters :params="filterParams" />
    <Card>
      <CardContent class="!p-0 !md:p-0">
        <AppLoader v-if="isLoading" variant="inline" subject="emergencies" />
        <AppError
          v-else-if="error"
          :error="error"
          title="Failed to load emergencies"
          variant="table"
          :action="refetch"
          action-text="Retry"
        />
        <AppEmpty v-else-if="!eventData || eventData.items.length === 0" subject="emergencies" variant="table" />
        <template v-else>
          <ResponsiveTable rounded>
            <ResponsiveTableHeader>
              <ResponsiveTableHead v-if="isAdminOrManager" class="text-accent-foreground text-xs sm:text-sm leading-6">
                Canvasser
              </ResponsiveTableHead>
              <ResponsiveTableHead class="text-accent-foreground text-xs sm:text-sm leading-6">
                Project
              </ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit text-nowrap">Triggered At</ResponsiveTableHead>
            </ResponsiveTableHeader>
            <ResponsiveTableBody>
              <ResponsiveTableRow
                v-for="item in eventData.items"
                :key="item.id"
                :to="{ name: 'emergencies-id', params: { id: item.id } }"
              >
                <ResponsiveTableCell v-if="isAdminOrManager" :cols="4" :cols-sm="4" label="Canvasser">
                  <UserNameWithCompany :user="item.canvasser" />
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="4" :cols-sm="2" label="Project">
                  <p class="text-base line-clamp-2">{{ item.project.name }}</p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="4" :cols-sm="2" label="Triggered At">
                  <p class="text-base md:text-center">
                    {{ formatDateTzToFormat(item.timestamp, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
                  </p>
                </ResponsiveTableCell>
              </ResponsiveTableRow>
            </ResponsiveTableBody>
            <ResponsiveTableFooter
              v-if="eventData.total_count > 0"
              :colspan="isAdminOrManager ? 3 : 2"
              :cols="4"
              :cols-sm="4"
            >
              <AppPagination
                :page="filterParams.page"
                :size="filterParams.size"
                :total="eventData.total_count"
                label="emergencies"
              />
            </ResponsiveTableFooter>
          </ResponsiveTable>
        </template>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getWakeWordEventList,
  type GetWakeWordEventListResponse,
  type WakeWordEventSortBy,
  type SortType,
} from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

definePageMeta({
  roles: ['admin', 'manager', 'canvasser', 'subcontractor_canvasser'],
  backLabel: 'emergencies',
});

useHead({
  title: 'Emergencies',
});

const route = useRoute();
const { timezone, isAdminOrManager } = useUserRole();

const filterParams = computed(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );

  const urlParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as WakeWordEventSortBy) || 'timestamp_ms',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    project_ids: processArrayQueryParameterFromUrl(route.query.project_ids),
    subcontractor_company_ids,
    include_unassigned,
    timestamp_from: (route.query.timestamp_from as string) || undefined,
    timestamp_to: (route.query.timestamp_to as string) || undefined,
  };
  return Object.fromEntries(Object.entries(urlParams).filter(([_, v]) => v !== undefined)) as typeof urlParams;
});

const {
  data: eventData,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['emergencies-list', filterParams.value],
  query: (): Promise<GetWakeWordEventListResponse> =>
    getWakeWordEventList({
      composable: '$fetch',
      query: filterParams.value,
    }),
  staleTime: 0,
});
</script>
